script_template:
#!/bin/bash
#SBATCH --job-name={{ job_name }}
#SBATCH --partition={{ partition }}
#SBATCH --account={{ account }}
#SBATCH --qos={{ qos }}
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --array={{ array_range }}
{% if gpu_count > 0 %}#SBATCH --gpus={{ gpu_count }}
{% endif %}#SBATCH --cpus-per-task={{ cpu_count }}
#SBATCH --time={{ time_hours }}:00:00
#SBATCH --output=logs/{{ job_name }}_%A_%a.out
#SBATCH --error=logs/{{ job_name }}_%A_%a.err

# 进入工作目录
cd {{ work_dir }} || { echo "目录 {{ work_dir }} 不存在"; exit 1; }

# 创建日志目录
mkdir -p logs

# 激活 conda 环境
source $(conda info --base)/etc/profile.d/conda.sh
conda activate {{ conda_env }} || { echo "conda 环境 {{ conda_env }} 激活失败"; exit 1; }

# 记录环境信息
echo "=========================================="
echo "作业 ID: $SLURM_ARRAY_JOB_ID"
echo "子任务 ID: $SLURM_ARRAY_TASK_ID"
echo "节点: $(hostname)"
echo "开始时间: $(date)"
echo "=========================================="

# 执行命令（$SLURM_ARRAY_TASK_ID 可用于区分不同子任务）
{{ command }}

echo "=========================================="
echo "子任务 $SLURM_ARRAY_TASK_ID 结束: $(date)"
echo "=========================================="
